Geocoding

postcodes &lt;- unique(biz_56111$postal_code)

url &lt;- "https://onemap.gov.sg/api/common/elastic/search"  ##API without paying

found &lt;- data.frame()
not_found &lt;- data.frame(postcode = character())

for (pc in postcodes) {
  query &lt;- list(
    searchVal = pc,
    returnGeom = "Y",
    getAddrDetails = "Y",
    pageNum = "1"
  )

###converting to data frame
res &lt;- GET(url, query = query)
json &lt;- content(res)

if (json$found != 0) {
  df &lt;- as.data.frame(json$results, stringsAsFactors = FALSE)
  df$input_postcode &lt;- pc
  found &lt;- bind_rows(found, df)
  } else {
  not_found &lt;- bind_rows(not_found, data.frame(postcode = pc))
  }
}

classify_time &lt;- function(day_type, time_hour){
  if(day_type == "WEEKDAYS"){
    if(time_hour &gt;= 6 & time_hour &lt;= 9) return("Weekday_AM_Peak")
    if(time_hour &gt;= 17 & time_hour &lt;= 20) return("Weekday_PM_Peak")
  } else if(day_type %in% c("WEEKENDS/HOLIDAY")){
    if(time_hour &gt;= 11 & time_hour &lt;= 20) return("Weekend_Peak")
  }
  return("Other")
}

